interface Task {
  readonly id: number;
  title: string;
  status: "todo" | "doing" | "done";
  dueDate: string | null;
}

type TaskPatch = Partial<Omit<Task, "id">>;

function applyPatch(task: Task, patch: TaskPatch): Task {
  return {
    ...task,
    title: patch.title ?? task.title,
    status: patch.status ?? task.status,
    dueDate: patch.dueDate === undefined ? task.dueDate : patch.dueDate,
  };
}

const task: Task = { id: 1, title: "Buy milk", status: "todo", dueDate: "2026-10-01" };
const a = applyPatch(task, { status: "doing" });
const b = applyPatch(task, { dueDate: null });
console.log(a.status, a.dueDate, "|", b.status, b.dueDate);

