type Status = "todo" | "doing" | "done";

function countByStatus(tasks: readonly { status: Status }[]): Record<Status, number> {
  const counts: Record<Status, number> = { todo: 0, doing: 0, done: 0 };
  for (const task of tasks) counts[task.status] += 1;
  return counts;
}

console.log(countByStatus([{ status: "todo" }, { status: "done" }, { status: "todo" }]));

